 for(unsigned which=0;which<2;++which){auto changed=pb;if(which==0)put(changed,24,word(changed.data()+24)+1);else put(changed,policy+40,bits(1.f));seal(changed);PoisonHazardsData different;CHECK(different.load(changed.data(),changed.size(),error));fail(deliver_poison_player_damage(different,PoisonContactKind::Area,area,true,FieldStepBody::Player,false,1,2,actor,c,run,&shadow,events,error));}
 {auto changed=wb;const auto first=word(changed.data()+132);put(changed,first+8,word(changed.data()+first+8)|4U);seal(changed);WorldDamageData incompatible;CHECK(incompatible.load(changed.data(),changed.size(),error));WorldDamageActor other_actor;CHECK(other_actor.prepare_after_reset(incompatible,1,2,c,error));const auto snapshot=state(other_actor,c,run,shadow);CHECK(!deliver_poison_player_damage(poison,PoisonContactKind::Area,area,true,FieldStepBody::Player,false,1,2,other_actor,c,run,&shadow,events,error));CHECK(state(other_actor,c,run,shadow)==snapshot);}
