 CHECK(actor.retire(1,2,error));CHECK(!deliver_poison_player_damage(poison,PoisonContactKind::Area,area,true,FieldStepBody::Player,false,1,2,actor,c,run,&shadow,events,error));std::cout<<checks<<" combined poison damage checks, "<<failures<<" failures\n";return failures?1:0;
